    [["a", "b", "c"], true],
    // Long chain
    [["ab", "bc", "cd", "de", "ef", "fg"], true],
    // Cycle
    [["abc", "bcd", "cda"], false],
    // Same letter multiple times
    [["aba", "bab"], false],
  ];

  for (const [arr, want] of tests) {
    const got = canFormSupersequence(arr);
    if (got !== want) {
      throw new Error(
        `\ncanFormSupersequence(${JSON.stringify(arr)}): got: ${got}, want: ${want}\n`,
      );
    }
  }
}

